{"path":"lib/posts.ts","content":"import type { Comment, Post } from '@/types/blog'

const POSTS_URL = 'https://jsonplaceholder.typicode.com/posts'

export async function getRecentPosts(): Promise<Post[]> {
  const response = await fetch(`${POSTS_URL}?_limit=5`, {
    cache: 'no-store',
  })

  return (await response.json()) as Post[]
}

export async function getAllPosts(): Promise<Post[]> {
  const response = await fetch(POSTS_URL, {
    next: { revalidate: 60 },
  })

  return (await response.json()) as Post[]
}

export async function getPost(id: string): Promise<Post> {
  const response = await fetch(`${POSTS_URL}/${id}`, {
    next: { revalidate: 300 },
  })

  if (!response.ok) {
    throw new Error(`Failed to fetch post ${id}`)
  }

  return (await response.json()) as Post
}

export async function getComments(id: string): Promise<Comment[]> {
  const response = await fetch(`${POSTS_URL}/${id}/comments`, {
    next: { revalidate: 300 },
  })

  if (!response.ok) {
    throw new Error(`Failed to fetch comments for post ${id}`)
  }

  return (await response.json()) as Comment[]
}

export function isPost(value: Post | null | undefined): value is Post {
  return (
    typeof value?.id === 'number' &&
    typeof value.title === 'string' &&
    typeof value.body === 'string'
  )
}
"}

