{"path":"app/blog/[id]/page.tsx","content":"import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { BackButton } from '@/components/NavigationButton'
import { getComments, getPost, getAllPosts, isPost } from '@/lib/posts'
import type { Post } from '@/types/blog'

export const revalidate = 300
export const dynamicParams = true

type BlogPostPageProps = {
  params: Promise<{
    id: string
  }>
}

export async function generateStaticParams(): Promise<Array<{ id: string }>> {
  const posts = await getAllPosts()

  return posts.slice(0, 10).map((post: Post) => ({
    id: post.id.toString(),
  }))
}

export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params

  try {
    const post = await getPost(id)

    if (!isPost(post)) {
      return {
        title: '404 - Page Not Found',
        description: "The page you're looking for doesn't exist",
      }
    }

    const description = post.body.substring(0, 160)

    return {
      title: `${post.title} - My Blog`,
      description,
      openGraph: {
        title: post.title,
        description,
      },
    }
  } catch {
    return {
      title: '404 - Page Not Found',
      description: "The page you're looking for doesn't exist",
    }
  }
}

export default async function BlogPostPage({ params }: BlogPostPageProps) {
  const { id } = await params

  try {
    const [post, comments] = await Promise.all([
      getPost(id),
      getComments(id),
    ])

    if (!isPost(post) || !Array.isArray(comments)) {
      notFound()
    }

    return (
      <article>
        <BackButton>← Back</BackButton>

        <h1>{post.title}</h1>
        <p>{post.body}</p>

        <h2>Comments ({comments.length})</h2>
        <div className="comments">
          {comments.map((comment) => (
            <div key={comment.id} className="comment">
              <h3>{comment.name}</h3>
              <p>{comment.body}</p>
              <small>By: {comment.email}</small>
            </div>
          ))}
        </div>
      </article>
    )
  } catch {
    notFound()
  }
}
"}

