{"path":"app/api/posts/route.ts","content":"import { NextResponse, type NextRequest } from 'next/server'
import { methodNotAllowed } from '@/lib/method-not-allowed'
import type { ApiError, ApiPost, ApiPostInput } from '@/types/api'

const ALLOWED_METHODS = ['GET', 'POST'] as const

export async function GET(): Promise<NextResponse<ApiPost[]>> {
  const posts: ApiPost[] = [
    { id: 1, title: 'First Post', content: 'This is the first post' },
    { id: 2, title: 'Second Post', content: 'This is the second post' },
  ]

  return NextResponse.json(posts, { status: 200 })
}

export async function POST(
  request: NextRequest,
): Promise<NextResponse<ApiPost | ApiError>> {
  const body = (await request.json()) as ApiPostInput
  const { title, content } = body

  if (!title || !content) {
    return NextResponse.json(
      { error: 'Title and content are required' },
      { status: 400 },
    )
  }

  const newPost: ApiPost = {
    id: Date.now(),
    title,
    content,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(newPost, { status: 201 })
}

export function PUT(request: NextRequest): NextResponse {
  return methodNotAllowed(request, ALLOWED_METHODS)
}

export function PATCH(request: NextRequest): NextResponse {
  return methodNotAllowed(request, ALLOWED_METHODS)
}

export function DELETE(request: NextRequest): NextResponse {
  return methodNotAllowed(request, ALLOWED_METHODS)
}

export function HEAD(request: NextRequest): NextResponse {
  return methodNotAllowed(request, ALLOWED_METHODS)
}

export function OPTIONS(request: NextRequest): NextResponse {
  return methodNotAllowed(request, ALLOWED_METHODS)
}
"}

